<script>import {snapshot,clock,selected} from '../state.js';import Topology from '../components/Topology.svelte';import {edgeState,labels,sessionGet,sessionSet} from '../lib.js';let scope=sessionGet('topology.scope','all'),view=sessionGet('topology.view','map');$: sessionSet('topology.scope',scope);$: sessionSet('topology.view',view);$: nodes=$snapshot?.nodes||[];$: edgeMap=new Map(($snapshot?.edges||[]).map(e=>[e.from+'>'+e.to,e]));$: rows=scope==='all'?nodes.slice(0,12):nodes.filter(n=>n.id===scope);$: columns=scope==='all'?nodes.slice(0,12):nodes;function edge(a,b){return edgeMap.get(a.id+'>'+b.id);}</script>
<section class="panel"><header class="panel-header"><div class="tabs"><button class:active={view==='map'} onclick={()=>view='map'}>接続図</button><button class:active={view==='matrix'} onclick={()=>view='matrix'}>接続マトリクス</button></div><label class="inline-field">観測元 <select bind:value={scope} aria-label="接続図の観測元"><option value="all">すべての観測</option>{#each nodes as n (n.id)}<option value={n.id}>{n.name}</option>{/each}</select></label></header><div hidden={view!=='map'}><Topology {scope}/></div><div hidden={view!=='matrix'} class="table-scroll">{#if nodes.length>12&&scope==='all'}<p class="graph-limit">一覧は先頭12台。観測元を選択すると、そのノードから全{nodes.length}台への結果を表示します。</p>{/if}<table class="matrix"><thead><tr><th>送信元 ↓ / 宛先 →</th>{#each columns as n (n.id)}<th>{n.name}</th>{/each}</tr></thead><tbody>{#each rows as a (a.id)}<tr><th>{a.name}</th>{#each columns as b (b.id)}<td>{#if a.id===b.id}<span class="quiet">—</span>{:else}{@const state=edgeState(edge(a,b),$snapshot,$clock)}<button class="matrix-cell {state}" onclick={()=>selected.set({kind:'edge',from:a.id,to:b.id})}><span class="dot"></span>{labels[state]}</button>{/if}</td>{/each}</tr>{/each}</tbody></table></div></section>
<div class="note-grid"><div><h3>矢印は観測方向</h3><p>「AからBへ接続できた」と「BからAへ接続できた」は別の結果です。線を選ぶとCQL・7000・Scope APIを確認できます。</p></div><div><h3>破線は未観測</h3><p>エージェント未導入や古い情報を「DOWN」とは扱いません。データ複製経路やRaftリーダーを表す図ではありません。</p></div></div>
